/**
 * Suggest spelling correction for search query
 * V3: Client-side typo correction using Levenshtein distance
 * 
 * @param query - The potentially misspelled search query
 * @param recentSearches - Array of recent valid searches to match against
 * @returns Suggested correction or null if no close match found
 * 
 * @example
 * suggestSpellingCorrection('bycicle', ['bicycle', 'tricycle', 'scooter'])
 * // Returns: 'bicycle'
 */
export function suggestSpellingCorrection(
  query: string,
  recentSearches: string[]
): string | null {
  if (!query || query.trim().length === 0) {
    return null;
  }

  if (!recentSearches || recentSearches.length === 0) {
    return null;
  }

  // Use Levenshtein distance with threshold 3
  return findClosestMatch(query.trim(), recentSearches, 3);
}

/**
 * Unit tests for fuzzyMatch utility
 * MODULE-05-DISCOVERY-V3: TASK DISCOVERY-V3-004
 */

import { levenshteinDistance, findClosestMatch } from '../../utils/fuzzyMatch';

describe('fuzzyMatch utilities', () => {
  describe('levenshteinDistance', () => {
    it('should return 0 for identical strings', () => {
      expect(levenshteinDistance('hello', 'hello')).toBe(0);
      expect(levenshteinDistance('', '')).toBe(0);
    });

    it('should return string length for empty string comparison', () => {
      expect(levenshteinDistance('', 'abc')).toBe(3);
      expect(levenshteinDistance('abc', '')).toBe(3);
    });

    it('should calculate correct distance for single character changes', () => {
      expect(levenshteinDistance('kitten', 'sitting')).toBe(3);
      expect(levenshteinDistance('bicycle', 'bycicle')).toBe(1);
    });

    it('should handle case sensitivity', () => {
      expect(levenshteinDistance('Hello', 'hello')).toBe(1);
    });

    it('should calculate distance for completely different strings', () => {
      const dist = levenshteinDistance('abc', 'xyz');
      expect(dist).toBeGreaterThan(0);
    });
  });

  describe('findClosestMatch', () => {
    const candidates = ['bicycle', 'tricycle', 'scooter', 'skateboard'];

    it('should find exact match (distance 0)', () => {
      expect(findClosestMatch('bicycle', candidates, 3)).toBe('bicycle');
    });

    it('should find close typo match (distance 1)', () => {
      expect(findClosestMatch('bycicle', candidates, 3)).toBe('bicycle');
    });

    it('should return null when distance exceeds threshold', () => {
      expect(findClosestMatch('xyz', candidates, 2)).toBeNull();
    });

    it('should be case-insensitive', () => {
      expect(findClosestMatch('BICYCLE', candidates, 3)).toBe('bicycle');
      expect(findClosestMatch('BiCyClE', candidates, 3)).toBe('bicycle');
    });

    it('should handle empty query', () => {
      expect(findClosestMatch('', candidates, 3)).toBeNull();
      expect(findClosestMatch('   ', candidates, 3)).toBeNull();
    });

    it('should handle empty candidates array', () => {
      expect(findClosestMatch('bicycle', [], 3)).toBeNull();
    });

    it('should return the best match when multiple within threshold', () => {
      const result = findClosestMatch('bicycl', candidates, 3);
      expect(result).toBe('bicycle'); // closest match
    });

    it('should handle custom threshold', () => {
      // With threshold 1, 'scootr' is too far from 'scooter'
      expect(findClosestMatch('scootr', candidates, 1)).toBe('scooter');

      // With threshold 0, only exact matches work
      expect(findClosestMatch('bicycle', candidates, 0)).toBe('bicycle');
      expect(findClosestMatch('bycicle', candidates, 0)).toBeNull();
    });

    it('should trim whitespace from query', () => {
      expect(findClosestMatch('  bicycle  ', candidates, 3)).toBe('bicycle');
    });
  });
});

/**
 * Unit tests for searchHistory service
 * MODULE-05-DISCOVERY-V3: TASK DISCOVERY-V3-003
 */

import AsyncStorage from '@react-native-async-storage/async-storage';
import {
  getRecentSearches,
  addSearchToHistory,
  removeSearchFromHistory,
  clearSearchHistory,
  getAutocompleteSuggestions,
} from '../../services/searchHistory';

// Mock AsyncStorage
jest.mock('@react-native-async-storage/async-storage', () => ({
  getItem: jest.fn(),
  setItem: jest.fn(),
  removeItem: jest.fn(),
}));

const STORAGE_KEY = '@kids_marketplace:recent_searches';

describe('searchHistory service', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('getRecentSearches', () => {
    it('should return empty array when no history exists', async () => {
      (AsyncStorage.getItem as jest.Mock).mockResolvedValue(null);

      const result = await getRecentSearches();

      expect(result).toEqual([]);
      expect(AsyncStorage.getItem).toHaveBeenCalledWith(STORAGE_KEY);
    });

    it('should return stored searches', async () => {
      const storedSearches = ['LEGO', 'bicycle', 'books'];
      (AsyncStorage.getItem as jest.Mock).mockResolvedValue(JSON.stringify(storedSearches));

      const result = await getRecentSearches();

      expect(result).toEqual(storedSearches);
    });

    it('should handle invalid JSON gracefully', async () => {
      (AsyncStorage.getItem as jest.Mock).mockResolvedValue('invalid json');

      const result = await getRecentSearches();

      expect(result).toEqual([]);
    });

    it('should handle storage errors gracefully', async () => {
      (AsyncStorage.getItem as jest.Mock).mockRejectedValue(new Error('Storage error'));

      const result = await getRecentSearches();

      expect(result).toEqual([]);
    });
  });

  describe('addSearchToHistory', () => {
    it('should add new search to empty history', async () => {
      (AsyncStorage.getItem as jest.Mock).mockResolvedValue(null);

      await addSearchToHistory('LEGO');

      expect(AsyncStorage.setItem).toHaveBeenCalledWith(
        STORAGE_KEY,
        JSON.stringify(['LEGO'])
      );
    });

    it('should prepend new search to existing history (LRU)', async () => {
      const existing = ['bicycle', 'books'];
      (AsyncStorage.getItem as jest.Mock).mockResolvedValue(JSON.stringify(existing));

      await addSearchToHistory('LEGO');

      expect(AsyncStorage.setItem).toHaveBeenCalledWith(
        STORAGE_KEY,
        JSON.stringify(['LEGO', 'bicycle', 'books'])
      );
    });

    it('should deduplicate case-insensitive', async () => {
      const existing = ['bicycle', 'LEGO', 'books'];
      (AsyncStorage.getItem as jest.Mock).mockResolvedValue(JSON.stringify(existing));

      await addSearchToHistory('lego'); // lowercase version

      expect(AsyncStorage.setItem).toHaveBeenCalledWith(
        STORAGE_KEY,
        JSON.stringify(['lego', 'bicycle', 'books']) // moved to front, old removed
      );
    });

    it('should cap at 8 searches maximum', async () => {
      const existing = ['s1', 's2', 's3', 's4', 's5', 's6', 's7', 's8'];
      (AsyncStorage.getItem as jest.Mock).mockResolvedValue(JSON.stringify(existing));

      await addSearchToHistory('new search');

      const savedData = JSON.parse(
        (AsyncStorage.setItem as jest.Mock).mock.calls[0][1]
      );

      expect(savedData).toHaveLength(8);
      expect(savedData[0]).toBe('new search');
      expect(savedData).not.toContain('s8'); // oldest evicted
    });

    it('should ignore empty or whitespace-only queries', async () => {
      (AsyncStorage.getItem as jest.Mock).mockResolvedValue(null);

      await addSearchToHistory('');
      await addSearchToHistory('   ');

      expect(AsyncStorage.setItem).not.toHaveBeenCalled();
    });

    it('should trim whitespace from query', async () => {
      (AsyncStorage.getItem as jest.Mock).mockResolvedValue(null);

      await addSearchToHistory('  LEGO  ');

      expect(AsyncStorage.setItem).toHaveBeenCalledWith(
        STORAGE_KEY,
        JSON.stringify(['LEGO'])
      );
    });
  });

  describe('removeSearchFromHistory', () => {
    it('should remove matching search (case-insensitive)', async () => {
      const existing = ['LEGO', 'bicycle', 'books'];
      (AsyncStorage.getItem as jest.Mock).mockResolvedValue(JSON.stringify(existing));

      await removeSearchFromHistory('lego'); // lowercase

      expect(AsyncStorage.setItem).toHaveBeenCalledWith(
        STORAGE_KEY,
        JSON.stringify(['bicycle', 'books'])
      );
    });

    it('should handle non-existent search gracefully', async () => {
      const existing = ['LEGO', 'bicycle'];
      (AsyncStorage.getItem as jest.Mock).mockResolvedValue(JSON.stringify(existing));

      await removeSearchFromHistory('books');

      expect(AsyncStorage.setItem).toHaveBeenCalledWith(
        STORAGE_KEY,
        JSON.stringify(['LEGO', 'bicycle'])
      );
    });
  });

  describe('clearSearchHistory', () => {
    it('should remove storage key', async () => {
      await clearSearchHistory();

      expect(AsyncStorage.removeItem).toHaveBeenCalledWith(STORAGE_KEY);
    });

    it('should handle errors gracefully', async () => {
      (AsyncStorage.removeItem as jest.Mock).mockRejectedValue(new Error('Storage error'));

      await expect(clearSearchHistory()).resolves.not.toThrow();
    });
  });

  describe('getAutocompleteSuggestions', () => {
