      mockRpc.mockResolvedValue({ data: mockSearchResults, error: null } as any);

      await searchListings('test', {});

      expect(mockRpc).toHaveBeenCalledWith('search_listings', {
        p_query: 'test',
        p_sp_eligible_only: false,
        p_limit: 20,
        p_offset: 0,
        p_category_ids: null,
        p_condition: null,
        p_min_price: null,
        p_max_price: null,
        p_age_group: null,
        p_gender: null,
        p_brand: null,
        p_colors: null,
