      const result = suggestSpellingCorrection('BYCICLE', recentSearches);

      expect(result).toBe('bicycle');
    });

    it('should return null for empty query', () => {
      expect(suggestSpellingCorrection('', recentSearches)).toBeNull();
      expect(suggestSpellingCorrection('   ', recentSearches)).toBeNull();
